import pandas as pd

def clean(df):
    df = df.copy()
    # strip whitespace from text columns
    for col in ["penguin_id", "species", "island", "sex"]:
        if col in df.columns:
            df[col] = df[col].astype(object).apply(lambda x: x.strip() if isinstance(x, str) else x)
    # standardise categorical labels
    if "species" in df.columns:
        df["species"] = df["species"].astype(str).str.strip().str.title()
    if "island" in df.columns:
        df["island"] = df["island"].astype(str).str.strip()
    if "sex" in df.columns:
        df["sex"] = df["sex"].astype(str).str.strip().str.lower()
        df["sex"] = df["sex"].replace({"nan": pd.NA, "None": pd.NA, "": pd.NA})
    # convert columns that are written as text to numeric
    num_cols = ["bill_length_mm", "bill_depth_mm", "flipper_length_mm", "body_mass_g", "year"]
    for c in num_cols:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors="coerce")
    # enforce body_mass_g range from rules
    if "body_mass_g" in df.columns:
        df = df[(df["body_mass_g"] >= 2500) & (df["body_mass_g"] <= 6500)]
    return df

def answer(df):
    sub = df.dropna(subset=["sex", "body_mass_g"])
    sub = sub[sub["sex"].isin(["male", "female"])]
    means = sub.groupby("sex")["body_mass_g"].mean()
    return {sex: float(mean) for sex, mean in means.items()}
